using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace ShotOut {
partial class Editor {
    public void VerifyDocumentationTools(List<string> report,string folder){
        Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};AnnotationLibrary.ResetForTests();var library=AnnotationLibrary.Current;
        var source=new Mark {Kind="Rectangle",Name="Do not save layer name",Text="Do not save document text",X=83,Y=91,W=130,H=50,Color=Color.RoyalBlue.ToArgb(),FillColor=Color.Gold.ToArgb(),Fill=true,FillOpacity=47,Width=7,Radius=14,Size=35,Shadow=true,ShadowSize=12,ShadowIntensity=61,Bold=false,Italic=true,Underline=true,TextAlignment=2};
        var preset=AnnotationPreset.Capture("Review highlight",source);library.Styles.Add(preset);check(library.AddFavorite(Color.Coral)&&!library.AddFavorite(Color.Coral),"Favorite colors deduplicate identical RGB values");library.AddFavorite(Color.MidnightBlue);string path=Path.Combine(folder,"annotation-library.xml");library.Save(path);var read=AnnotationLibrary.Read(path);check(read.Styles.Count==1&&read.Styles[0].Name==preset.Name&&read.Styles[0].FillColor==source.FillColor&&read.Styles[0].FillOpacity==47&&read.Styles[0].ShadowIntensity==61,"Named styles persist colors, fill, stroke, text, and shadow settings");check(read.FavoriteColors.SequenceEqual(library.FavoriteColors),"Favorite colors survive a saved-library round trip");check(!File.ReadAllText(path).Contains("Do not save"),"Saved styles exclude document text, image data, and layer names");
        read.Styles[0].Name="Renamed style";read.Save(path);check(AnnotationLibrary.Read(path).Styles[0].Name=="Renamed style","Style names can be renamed persistently");read.Styles.Clear();read.Save(path);check(AnnotationLibrary.Read(path).Styles.Count==0,"Deleting a saved style persists");
        LoadImageDocument(Blank(700,420),"Documentation tools");SetTool("Rectangle");ApplyAnnotationPreset(preset);using(var timer=new Timer {Interval=20}){int attempts=0;timer.Tick+=delegate{var prompt=Application.OpenForms.Cast<Form>().OfType<ApplyPrompt>().FirstOrDefault(form=>form.Text.StartsWith("Save style"));if(prompt!=null){timer.Stop();prompt.Controls.OfType<TextBox>().Single().Text="Saved through UI";prompt.ApplyText();}else if(++attempts>100){timer.Stop();throw new Exception("Style save prompt did not appear");}};timer.Start();SaveAnnotationPreset();}check(library.Styles.Any(style=>style.Name=="Saved through UI"&&style.Color==source.Color&&style.Width==7),"Save current style dialog captures the actual tool settings");var next=NewMark("Rectangle",new PointF(22,31));check(next.Color==source.Color&&next.Width==7&&next.Fill&&next.FillOpacity==47&&next.Radius==14&&next.X==22&&next.Y==31,"Applying a preset to a drawing tool sets new annotation defaults");thickness.Value=9;check(NewMark("Rectangle",PointF.Empty).Width==9,"Manual adjustments remain available after applying a saved style");
        var first=new Mark {Kind="Rectangle",X=30,Y=40,W=70,H=40,Text="Preserve this content"};var second=new Mark {Kind="Rectangle",X=220,Y=130,W=90,H=60};Marks.Add(first);Marks.Add(second);SetTool("Select");Active=first;Selected.Clear();Selected.Add(first);Selected.Add(second);int history=undo.Count;ApplyAnnotationPreset(preset);check(first.X==30&&first.Y==40&&first.W==70&&first.H==40&&first.Text=="Preserve this content"&&first.Width==7&&second.Color==source.Color,"Styles apply to matching selected objects without replacing their geometry or content");check(undo.Count==history+1,"Applying a style to multiple objects creates one Undo step");Undo();check(Marks.Skip(1).All(mark=>mark.Width==3),"Undo restores original annotation styles");
        SetTool("Balloon");var bubblePreset=AnnotationPreset.Capture("Right aligned bubble",new Mark {Kind="Balloon",TextAlignment=2,Radius=18,Fill=true,FillColor=Color.LightBlue.ToArgb(),Size=32});ApplyAnnotationPreset(bubblePreset);check(NewMark("Balloon",PointF.Empty).TextAlignment==2,"Speech-bubble presets retain default text alignment");SetTool("Arrow");SetTool("Balloon");check(NewMark("Balloon",PointF.Empty).TextAlignment==2,"Preset text alignment survives tool switching");
        var words=new Mark {Kind="Text",Text="Keep words",X=10,Y=10,W=130,H=40,Size=22,Bold=true};words.Runs.Add(new TextRun {Text="Keep words",Style=1});var textStyle=AnnotationPreset.Capture("Italic text",new Mark {Kind="Text",Size=30,Bold=false,Italic=true,Underline=true});textStyle.Apply(words);check(words.Text=="Keep words"&&words.Runs.Count==1&&words.Runs[0].Style==6,"Text presets update rich formatting while preserving text");
        foreach(int operation in Enumerable.Range(0,8)){
            LoadImageDocument(Blank(700,420),"Layout "+operation);var a=new Mark {Kind="Rectangle",X=30,Y=30,W=70,H=30};var b=new Mark {Kind="Ellipse",X=180,Y=110,W=110,H=50};var c=new Mark {Kind="Rectangle",X=440,Y=300,W=40,H=60};Marks.AddRange(new[]{a,b,c});Active=b;Selected.Clear();foreach(var mark in new[]{a,b,c})Selected.Add(mark);history=undo.Count;var sizes=new[]{a.BodyBounds.Size,b.BodyBounds.Size,c.BodyBounds.Size};ArrangeSelection(operation);var units=LayoutUnits();
            if(operation<6){float[] positions=units.Select(unit=>operation==0?unit.Bounds.Left:operation==1?unit.Bounds.Left+unit.Bounds.Width/2:operation==2?unit.Bounds.Right:operation==3?unit.Bounds.Top:operation==4?unit.Bounds.Top+unit.Bounds.Height/2:unit.Bounds.Bottom).ToArray();check(positions.All(value=>Math.Abs(value-positions[0])<.01),"Alignment operation "+operation+" positions all selected objects correctly");}
            else{bool horizontal=operation==6;var ordered=units.OrderBy(unit=>horizontal?unit.Bounds.Left:unit.Bounds.Top).ToArray();float gap1=horizontal?ordered[1].Bounds.Left-ordered[0].Bounds.Right:ordered[1].Bounds.Top-ordered[0].Bounds.Bottom,gap2=horizontal?ordered[2].Bounds.Left-ordered[1].Bounds.Right:ordered[2].Bounds.Top-ordered[1].Bounds.Bottom;check(Math.Abs(gap1-gap2)<.01&&a.X==30&&a.Y==30&&c.X==440&&c.Y==300,"Distribution "+operation+" creates equal gaps and preserves the outer objects");}
            check(a.BodyBounds.Size==sizes[0]&&b.BodyBounds.Size==sizes[1]&&c.BodyBounds.Size==sizes[2],"Layout operation "+operation+" preserves object dimensions");check(undo.Count==history+1,"Layout operation "+operation+" is a single Undo action");Undo();check(Marks[2].X==180&&Marks[2].Y==110,"Undo restores layout operation "+operation);Redo();
        }
        LoadImageDocument(Blank(700,420),"Linked layout");var image=Marks[0];image.ImageMovementLocked=false;image.X=20;image.Y=60;image.W=140;image.H=90;image.LinkId="linked";var linkedLabel=new Mark {Kind="Text",Text="Linked label",X=30,Y=155,W=130,H=30,LinkId="linked"};var other=new Mark {Kind="Rectangle",X=350,Y=240,W=120,H=80};Marks.Add(linkedLabel);Marks.Add(other);Active=other;Selected.Clear();Selected.Add(image);Selected.Add(other);ArrangeSelection(3);check(linkedLabel.Y-image.Y==95&&LayoutUnits().Count==2,"Alignment keeps linked image and annotation geometry together");history=undo.Count;ArrangeSelection(6);check(undo.Count==history,"Distribution with fewer than three independent groups leaves history unchanged");
        using(var menu=CreateArrangeMenu()){check(!menu.DropDownItems.Cast<ToolStripItem>().Last().Enabled,"Spacing menu is disabled for fewer than three independent groups");((ToolStripMenuItem)menu.DropDownItems[0]).PerformClick();Application.DoEvents();check(other.X==image.X,"Alignment menu click executes its selected action");Undo();}Active=Marks.Last();Selected.Clear();Selected.Add(Marks[0]);Selected.Add(Active);Show();Application.DoEvents();UpdateInspector();check(arrangeRow.Visible,"Multiple selection exposes alignment controls in the inspector");using(var frame=new Bitmap(Width,Height)){DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(folder,"documentation-layout.png"));}Hide();
        using(var picker=new PaletteDialog(Color.CornflowerBlue)){check(picker.Chosen.ToArgb()==Color.CornflowerBlue.ToArgb(),"Expanded color picker preserves the initial color");picker.Show();Application.DoEvents();picker.AcceptScreenColor(null);check(picker.Chosen.ToArgb()==Color.CornflowerBlue.ToArgb(),"Cancelling the eyedropper leaves the selected color unchanged");picker.AcceptScreenColor(Color.OrangeRed);check(picker.Chosen.ToArgb()==Color.OrangeRed.ToArgb()&&picker.Controls.OfType<TextBox>().Single().Text=="#FF4500","Eyedropper selection updates the color, hex field, and spectrum");picker.Controls.OfType<TextBox>().Single().Text="#123456";picker.Controls.OfType<ModernButton>().First(button=>button.Text=="Save favorite").PerformClick();check(library.FavoriteColors.Contains(Color.FromArgb(0x12,0x34,0x56).ToArgb()),"Save favorite reads and saves the entered hexadecimal color");using(var frame=new Bitmap(picker.Width,picker.Height)){picker.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(folder,"favorite-color-picker.png"));}picker.Hide();}
        using(var desktop=new Bitmap(240,160)){using(var graphics=Graphics.FromImage(desktop)){graphics.Clear(Color.Navy);graphics.FillRectangle(Brushes.Lime,100,60,30,30);}using(var picker=new ScreenColorPicker(desktop,new Rectangle(-240,-160,240,160))){picker.SampleAt(new Point(110,70));check(picker.Chosen.ToArgb()==Color.Lime.ToArgb(),"Eyedropper samples exact source pixels on a synthetic negative-coordinate monitor");picker.SampleAt(new Point(-10,-20));check(picker.Chosen.ToArgb()==Color.Navy.ToArgb(),"Eyedropper safely clamps points at desktop boundaries");picker.SampleAt(new Point(110,70));using(var preview=new Bitmap(240,160)){picker.DrawToBitmap(preview,new Rectangle(Point.Empty,preview.Size));preview.Save(Path.Combine(folder,"eyedropper-preview.png"));}picker.CompleteSampling(false);check(picker.DialogResult==DialogResult.Cancel,"Eyedropper cancellation returns Cancel without applying a color");}}
        bool blocked=false;try{ScreenColorPicker.Pick(this);}catch(InvalidOperationException){blocked=true;}check(blocked,"Automated checks never capture or sample the real desktop");AnnotationLibrary.ResetForTests();presetAlignments.Clear();LoadBitmap(Blank(100,100),"Test");
    }
}
}
